const incoming = $input.first().json;
const lead = incoming.body ?? incoming;

const name = String(lead.name ?? '').trim();
const email = String(lead.email ?? '').trim().toLowerCase();
const company = String(lead.company ?? '').trim();
const message = String(lead.message ?? '').trim();
const budget = Number(lead.budget ?? 0);
const timeline = String(lead.timeline ?? '').toLowerCase();

if (!name || !email || !email.includes('@')) {
  return [{ json: {
    success: false,
    workflow: 'AI Lead Generation & CRM',
    error: 'A valid name and email are required.',
    received: { name, email }
  }}];
}

let score = 0;
const reasons = [];

if (budget >= 10000) { score += 35; reasons.push('Budget is 10,000 or above'); }
else if (budget >= 5000) { score += 25; reasons.push('Budget is 5,000 or above'); }
else if (budget > 0) { score += 10; reasons.push('Budget provided'); }

if (timeline.includes('immediate') || timeline.includes('week')) {
  score += 30; reasons.push('Urgent implementation timeline');
} else if (timeline.includes('month')) {
  score += 20; reasons.push('Implementation expected within a month');
} else if (timeline) {
  score += 10; reasons.push('Timeline provided');
}

if (company) { score += 15; reasons.push('Company information provided'); }
if (message.length >= 80) { score += 20; reasons.push('Detailed business requirement provided'); }
else if (message.length >= 20) { score += 10; reasons.push('Requirement details provided'); }

score = Math.min(score, 100);
const priority = score >= 70 ? 'HOT' : score >= 40 ? 'WARM' : 'COLD';

return [{ json: {
  success: true,
  workflow: 'AI Lead Generation & CRM',
  lead: { name, email, company, message, budget, timeline },
  qualification: { score, priority, reasons },
  recommendedAction: priority === 'HOT'
    ? 'Contact immediately and schedule a discovery call.'
    : priority === 'WARM'
      ? 'Send a personalized follow-up within 24 hours.'
      : 'Add to a long-term nurturing campaign.',
  processedAt: new Date().toISOString(),
  note: 'This starter workflow uses explainable rule-based scoring. Connect an LLM node to add AI-generated summaries or enrichment.'
}}];
